function validate([arr, k]) {
  if (!Array.isArray(arr) || arr.length < 1 || arr.length > 1000) return 'arr needs 1 to 1000 strings.';
  if (arr.some(s => typeof s !== 'string' || !/^[a-z]{1,5}$/.test(s))) return 'Each string has 1 to 5 lowercase letters.';
  if (!Number.isInteger(k) || k < 1 || k > arr.length) return 'k is between 1 and arr.length.';
  return null;
}

