function kthDistinct(arr, k) {
  const count = new Map();
  for (const word of arr) {
    count.set(word, (count.get(word) || 0) + 1);
  }

  for (const word of arr) {
    if (count.get(word) === 1) {
      k--;
      if (k === 0) {
        return word;
      }
    }
  }
  return "";
}

