function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? 1000 : int(1, 8);
  const letters = size === 'large' ? [2, 4, 26][int(0, 2)] : int(1, 3);
  const longest = size === 'large' ? [2, 3, 5][int(0, 2)] : int(1, 2);
  const word = () => {
    let s = '';
    for (let len = int(1, longest); len > 0; len--) s += String.fromCharCode(97 + int(0, letters - 1));
    return s;
  };
  const arr = Array.from({ length: n }, word);
  const k = rand() < 0.6 ? int(1, Math.min(n, 4)) : int(1, n);
  return [arr, k];
}
